static void lcd_cmd(uint8_t c)
{
    lcd_sync();
    fm1_lcd_send_cmd(c);
    fm1_lcd_wait();
    fm1_lcd_deselect();
}

/* the lights ("leds"): bright, and dim (glow 0: none); PLAY's green counts as PLAY */
void plat_lights(uint32_t b, uint32_t k, uint32_t db, uint32_t dk, int glow)
{
    lit_btn = (b & ((1u << NB) - 1u)) | (b & LED_PLAY_GREEN ? 1u << B_PLAY : 0u);
    lit_keys = k;
    db = (db & ((1u << NB) - 1u)) | (db & LED_PLAY_GREEN ? 1u << B_PLAY : 0u);
    dim_btn = glow ? db & ~lit_btn : 0u;
    dim_keys = glow ? dk & ~k : 0u;
}

static uint32_t st_crc32(const void *p, uint32_t n)   /* zlib CRC-32, 4 bits per step */
{
    static const uint32_t T[16] = {
        0x00000000u, 0x1DB71064u, 0x3B6E20C8u, 0x26D930ACu, 0x76DC4190u, 0x6B6B51F4u, 0x4DB26158u, 0x5005713Cu,
        0xEDB88320u, 0xF00F9344u, 0xD6D6A3E8u, 0xCB61B38Cu, 0x9B64C2B0u, 0x86D3D2D4u, 0xA00AE278u, 0xBDBDF21Cu};
    const uint8_t *b = p;
    uint32_t c = 0xFFFFFFFFu;
    while (n--) {
        c ^= *b++;
        c = (c >> 4) ^ T[c & 15u];
        c = (c >> 4) ^ T[c & 15u];
    }
    return ~c;
}

void touch_update(void)
{
    uint32_t i, now = plat_ms();
    float sens = 0.5f + (float)touch_s * 0.09f;
    if (!touch_live || now - p_t < 5u)
        return;
    p_t = now;
    for (i = 0; i < NKEYS; i++) {
        float d, lean, x;
        if (!sense_is_analog(i) || sn_key[i].st != SN_DOWN || !sn_key[i].dn) {
            p_on[i] = 0;
            p_s[i] = 0.0f;
            p_val[i] = 0;
            continue;
        }
        d = (float)(sn_key[i].d > SN_DBASE + 1u ? sn_key[i].d - SN_DBASE : 1u);
        if (!p_on[i]) {
            p_on[i] = 1;
            p_base[i] = d;
            p_t0[i] = now;
        }
        if (d > p_base[i])
            p_base[i] = d;                                     /* eased off: that is the rest now */
        else
            p_base[i] += (d - p_base[i]) * (now - p_t0[i] < P_SETTLE ? 0.25f : 0.0008f);
        lean = fm_log2f(p_base[i] / d);
        x = fm_clampf((lean - P_DEAD) / P_SPAN(sens), 0.0f, 1.0f);
        p_s[i] += (x - p_s[i]) * 0.17f;
        p_val[i] = (uint8_t)(p_s[i] * 127.0f + 0.5f);
    }
}

static void input(void)
{
    uint32_t btn = plat_buttons(), down = btn & ~ui.btn, up = ui.btn & ~btn, now = plat_ms();
    int i;
    int32_t e;
    if (ui.state == ST_BOOT) {                /* any control ends the boot animation */
        uint32_t sb = 0;
#if BOARD_SMK37
        sb = plat_smk_buttons() | plat_pads_held();
#endif
        if (down || sb) {
            ui.state = ST_RUN;
            ui.full = 1;
        }
    }
#if !BOARD_SMK37
    keys_input();
#endif
    if (down & (1u << B_OCTDN) && set.octave > -2) {
        set.octave--;
        changed();
        ui.oct_q = -99;
    }
    if (down & (1u << B_OCTUP) && set.octave < 2) {
        set.octave++;
        changed();
        ui.oct_q = -99;
    }
    if (down & (1u << B_HOME)) {
        page_set(PG_PLAY);
        ui.home_at = now;
    }
    if (btn & (1u << B_HOME)) {
        if (!ui.debug && now - ui.home_at > 800u) {   /* PATCH held: the audio load, the voices */
            ui.debug = 1;
            ui.head_q = -1;
        }
    } else if (ui.debug) {
        ui.debug = 0;
        ui.head_q = -1;
    }
    /* BT (the FM-1's SAVE): the settings saved now. The FM-1: held a second, the sound into the user preset that
     * PRESETS points at */
    if (down & (1u << B_SAVE)) {
        ui.save_at = now;
        ui.save_done = 0;
#if BOARD_SMK37
        settings_save();
        ui.save_done = 1;
#endif
    }
#if !BOARD_SMK37
    if ((btn & (1u << B_SAVE)) && !ui.save_done && now - ui.save_at >= LONG_MS) {
        slot_save(ui.slot_sel);
        ui.save_done = 1;
    }
    if ((up & (1u << B_SAVE)) && !ui.save_done)
        settings_save();
#endif
    pedal_buttons(down, up, now);             /* SCALE una corda, CHORD sostenuto, SEQ REC sustain */
    if (down & (1u << B_PLAY)) {              /* SEQ PLAY: the metronome (its tempo: the play screen's K4) */
        ui.metro = !ui.metro;
        ev_put(EV_METRO, (uint32_t)ui.metro);
    }
    if (down & (1u << B_FX))                  /* FX: every note let go */
        ev_put(EV_ALL_OFF, 0);
    ui.btn = btn;
#if BOARD_SMK37
    {                                         /* < >: the pages */
        uint32_t sb = plat_smk_buttons(), sd = sb & ~ui.sbtn;
        if (sd & (1u << SB_LEFT))
            page_set(ui.page - 1);
        if (sd & (1u << SB_RIGHT))
            page_set(ui.page + 1);
        ui.sbtn = sb;
    }
#endif
    for (i = 0; i < 4; i++)                   /* K1..K4 (the FM-1's KNOB 1..4): the page's four knobs */
        if ((e = plat_enc(EN_K1 + i)) != 0)
            knob_turn(ui.page, i, e);
#if BOARD_SMK37
    cc_controls(now);                         /* K6..K8 and the faders: MIDI CC out */
#else
    if ((e = plat_enc(EN_SELECT)) != 0)       /* the FM-1: SELECT the page */
        page_set(ui.page + e);
    if ((e = plat_enc(EN_ALGO)) != 0) {       /* ALGORITHM: the voices */
        int v = set.pad >= 1 && set.pad <= 4 ? set.pad - 1 + e : e > 0 ? 0 : 3;
        voice_select(clamp(v, 0, 3));
    }
    if ((e = plat_enc(EN_PRESET)) != 0) {     /* PRESETS: the user presets, recalled as it lands on them */
        ui.slot_sel = clamp(ui.slot_sel + e, 0, NSLOT - 1);
        slot_recall(ui.slot_sel);
    }
#endif
    pads_input();
    if (ui.active >= 0 && now - ui.active_at > 1200u) {
        ui.active = -1;
        ui.strip_q = -1;
    }
    /* saved by itself once the piano is quiet, the room's tail too (a flash write stops the sound and USB for a
     * moment): no note for 1.5 s */
    if (erk_active() || erk_pad_active())
        ui.quiet_at = now;
    if (set_dirty && now - set_changed_at > 2000u && now - ui.quiet_at > 1500u) {
        if (plat_store_save(OBJ_SETTINGS, &set, sizeof set) == 0)
            set_dirty = 0;
    }
}

static float fsin_(float x)
{
    float s = 1, x2;
    while (x > PI_F)
        x -= 2 * PI_F;
    while (x < -PI_F)
        x += 2 * PI_F;
    if (x > PI_F / 2) {
        x = PI_F - x;
    } else if (x < -PI_F / 2) {
        x = -PI_F - x;
    }
    x2 = x * x;
    return s * x * (1 - x2 / 6 * (1 - x2 / 20 * (1 - x2 / 42 * (1 - x2 / 72))));
}

static void proj(v3 p, int mirror, float *sx, float *sy, float *depth)
{
    v3 r = rot3(p);
    float y = mirror ? -r.y : r.y, Y = y * b_pc + r.z * b_ps;
    *sx = b_cx + b_sc * r.x;
    *sy = b_cy - b_sc * Y;
    *depth = r.z * b_pc - y * b_ps;
}

static void mask_fill(rgb_t c, float alpha)
{
    int x, y, a = AF(alpha);
    for (y = mbox.y0; y < mbox.y1; y++)
        for (x = mbox.x0; x < mbox.x1; x++) {
            int m = MASK[y * SW + x];
            if (m)
                blend(x, y, c, (m * a + 127) / 255);
        }
}

/* a time: "0.25 s" below a second, "1.2 s" from one */
static void secs_text(char *b, int ms)
{
    char t[8];
    b[0] = 0;
    if (ms < 1000) {
        int c = (ms + 5) / 10;
        cat_s(b, c < 10 ? "0.0" : "0.");
        itoa_s(c, t);
    } else {
        int d = (ms + 50) / 100;
        itoa_s(d / 10, t);
        cat_s(b, t);
        cat_s(b, ".");
        itoa_s(d % 10, t);
    }
    cat_s(b, t);
    cat_s(b, " s");
}

static void e0_chunk(void)
{
    uint32_t n = usb.e0_left > 64u ? 64u : usb.e0_left, i;
    int last;
    for (i = 0; i < n; i++)
        ep0buf[i] = usb.e0_src[i];
    fm1_usb_ep0_send(ep0buf, n);
    usb.e0_src += n;
    usb.e0_left = (uint16_t)(usb.e0_left - n);
    last = usb.e0_left == 0 && !(n == 64u && usb.e0_zlp);
    if (usb.e0_left == 0 && n == 64u)
        usb.e0_zlp = 0;
    sie_wr(S_INDEX, 0);
    sie_wr(S_CSR0, last ? 0x0A : 0x02);
    if (last)
        usb.e0_tx = 0;
}

static void e0_send(const uint8_t *p, uint16_t len, uint16_t wlen)
{
    if (len > wlen)
        len = wlen;
    usb.e0_src = p;
    usb.e0_left = len;
    usb.e0_zlp = (len < wlen) && (len % 64u == 0);
    usb.e0_tx = 1;
    sie_wr(S_INDEX, 0);
    sie_wr(S_CSR0, 0x40);
    e0_chunk();
}

static uint8_t fm1_p33_read(uint32_t a)
{
    uint8_t v;
    fm1__p33_cs(a);
    fm1__p33_xfer((uint8_t)(0x80u | ((a >> 8) & 3u)));
    fm1__p33_xfer((uint8_t)a);
    v = fm1__p33_xfer(0x5E);
    FM1_P33_CON &= ~((1u << 0) | (1u << 8));
    return v;
}

void erk_render_gain(int32_t *lr, int frames, int32_t master_q12)
{
    int f, i;
    for (f = 0; f < frames; f += ERK_BLOCK) {
        int32_t L[ERK_BLOCK], R[ERK_BLOCK], rl[ERK_BLOCK], rr[ERK_BLOCK], wl[ERK_BLOCK], wr[ERK_BLOCK];
        int32_t gt, mq, rlev;
        if (st.rev_dirty) {
            st.rev_dirty = 0;
            rev_apply();
        }
        memset(L, 0, sizeof L);
        memset(R, 0, sizeof R);
        memset(lvl_acc, 0, sizeof lvl_acc);
        for (i = 0; i < ERK_NV; i++)
            if (vc[i].state != V_FREE)
                voice_block(&vc[i], L, R);
        for (i = 0; i < ERK_KEYS; i++)
            erk_key_lvl[i] = lvl_acc[i];
        if (st.g_lo || st.g_hi) {
            eq_block(L, eq_l, st.g_lo, st.g_hi);
            eq_block(R, eq_r, st.g_lo, st.g_hi);
        }
        /* resonance: the pedal sets the send and how long the strings ring (RT ~3.5 s down, ~0.1 s up) */
        send += (send_t - send) >> 3;
        gt = sus ? 32767 : 0;
        ped += (gt - ped) >> 3;
        for (i = 0; i < NRES; i++)
            res_c[i].g = res_gup[i] + (((res_gdn[i] - res_gup[i]) * ped) >> 15);
        rlev = (st.res_level * (st.res_scale >> 4)) >> 11;
        if (rlev || ped > 64) {
            res_block(L, R, rl, rr);
            for (i = 0; i < ERK_BLOCK; i++) {
                L[i] += (rl[i] * rlev) >> 10;         /* 2^13 scale -> 2^18 */
                R[i] += (rr[i] * rlev) >> 10;
            }
        }
        pad_block(L, R);                              /* (nothing while no pad note sounds) */
        if (clk_n > 0)
            click_block(L, R);
        rev_mix += (st.rev_mix - rev_mix) >> 4;
        rev_w = (st.width >> 1) + 16384;
        if (rev_on) {
            rev_block(L, R, wl, wr);
            for (i = 0; i < ERK_BLOCK; i++) {
                L[i] += (wl[i] * rev_mix) >> 9;       /* 2^12 scale -> 2^18 */
                R[i] += (wr[i] * rev_mix) >> 9;
            }
        }
        mq = (st.master * clampi(master_q12, 0, 4096)) >> 15;   /* Q12 */
        for (i = 0; i < ERK_BLOCK; i++) {             /* 2^18 x Q12 -> 24 bit */
            lr[2 * (f + i)] = out24(L[i], mq);
            lr[2 * (f + i) + 1] = out24(R[i], mq);
        }
        erk_st.blocks++;
    }
}
